initJs:
function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = '';
  let sortDirection = 'asc';

  // 店舗選択肢を初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector('#store-filter');
    const stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];
    stores.forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = store.店舗名;
      storeSelect.appendChild(option);
    });
  }

  // 予測精度データの再描画
  function renderRows(rows) {
    const tbody = container.querySelector('#accuracy-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map((row, index) => {
      const store = tables.find(t => t.tableName === '店舗マスタ')?.records?.find(s => s.店舗ID === row.店舗ID);
      const product = tables.find(t => t.tableName === '商品マスタ')?.records?.find(p => p.商品ID === row.商品ID);
      const mape = calculateMAPE(row.予測数量, row.実績数量);
      const rmse = calculateRMSE(row.予測数量, row.実績数量);
      const accuracy = Math.max(0, 100 - mape);

      return `
        <tr data-id="${row.予測結果ID}">
          <td>${index + 1}</td>
          <td>${store?.店舗名 || '不明'}</td>
          <td>${product?.商品名 || '不明'}</td>
          <td>${mape.toFixed(2)}%</td>
          <td>${rmse.toFixed(2)}</td>
          <td style="color: ${accuracy >= 80 ? '#4ade80' : accuracy >= 60 ? '#fbbf24' : '#f87171'}">${accuracy.toFixed(1)}%</td>
          <td>${new Date(row.予測対象日).toLocaleDateString()}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.予測結果ID}">詳細分析</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // MAPE計算
  function calculateMAPE(predicted, actual) {
    if (!actual || actual === 0) return 0;
    return Math.abs((actual - predicted) / actual) * 100;
  }

  // RMSE計算
  function calculateRMSE(predicted, actual) {
    return Math.sqrt(Math.pow(actual - predicted, 2));
  }

  // グラフ描画
  function drawAccuracyChart() {
    const canvas = container.querySelector('#accuracy-chart');
    const ctx = canvas.getContext('2d');

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = 50;

    // 背景
    ctx.fillStyle = '#1e293b';
    ctx.fillRect(0, 0, width, height);

    // サンプルデータ
    const data = [
      { date: '1/1', mape: 18.5, rmse: 9.2 },
      { date: '1/8', mape: 16.8, rmse: 8.7 },
      { date: '1/15', mape: 15.2, rmse: 8.1 },
      { date: '1/22', mape: 14.9, rmse: 7.8 },
      { date: '1/29', mape: 15.8, rmse: 8.3 }
    ];

    // 軸
    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // MAPE線グラフ
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach((point, i) => {
      const x = padding + (i * (width - padding * 2) / (data.length - 1));
      const y = height - padding - ((point.mape / 25) * (height - padding * 2));
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('MAPE推移', padding, 20);
  }

  function drawComparisonChart() {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = 50;

    // 背景
    ctx.fillStyle = '#1e293b';
    ctx.fillRect(0, 0, width, height);

    // サンプルデータ
    const data = [
      { date: '1/1', predicted: 120, actual: 115 },
      { date: '1/2', predicted: 135, actual: 142 },
      { date: '1/3', predicted: 98, actual: 89 },
      { date: '1/4', predicted: 156, actual: 148 },
      { date: '1/5', predicted: 178, actual: 185 }
    ];

    // 軸
    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // 予測値線
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach((point, i) => {
      const x = padding + (i * (width - padding * 2) / (data.length - 1));
      const y = height - padding - ((point.predicted / 200) * (height - padding * 2));
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 実績値線
    ctx.strokeStyle = '#10b981';
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach((point, i) => {
      const x = padding + (i * (width - padding * 2) / (data.length - 1));
      const y = height - padding - ((point.actual / 200) * (height - padding * 2));
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('予測値', padding, 20);
    ctx.fillText('実績値', padding + 60, 20);
  }

  // ソート機能
  function sortData(column) {
    if (sortColumn === column) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortColumn = column;
      sortDirection = 'asc';
    }

    currentData.sort((a, b) => {
      let aVal, bVal;

      switch(column) {
        case 'rank':
          return 0; // 順位は固定
        case 'store_name':
          const storeA = tables.find(t => t.tableName === '店舗マスタ')?.records?.find(s => s.店舗ID === a.店舗ID);
          const storeB = tables.find(t => t.tableName === '店舗マスタ')?.records?.find(s => s.店舗ID === b.店舗ID);
          aVal = storeA?.店舗名 || '';
          bVal = storeB?.店舗名 || '';
          break;
        case 'product_name':
          const productA = tables.find(t => t.tableName === '商品マスタ')?.records?.find(p => p.商品ID === a.商品ID);
          const productB = tables.find(t => t.tableName === '商品マスタ')?.records?.find(p => p.商品ID === b.商品ID);
          aVal = productA?.商品名 || '';
          bVal = productB?.商品名 || '';
          break;
        case 'mape':
          aVal = calculateMAPE(a.予測数量, a.実績数量);
          bVal = calculateMAPE(b.予測数量, b.実績数量);
          break;
        case 'rmse':
          aVal = calculateRMSE(a.予測数量, a.実績数量);
          bVal = calculateRMSE(b.予測数量, b.実績数量);
          break;
        case 'accuracy':
          aVal = Math.max(0, 100 - calculateMAPE(a.予測数量, a.実績数量));
          bVal = Math.max(0, 100 - calculateMAPE(b.予測数量, b.実績数量));
          break;
        case 'period':
          aVal = new Date(a.予測対象日);
          bVal = new Date(b.予測対象日);
          break;
        default:
          return 0;
      }

      if (typeof aVal === 'string') {
        return sortDirection === 'asc' ? aVal.localeCompare(bVal) : bVal.localeCompare(aVal);
      } else {
        return sortDirection === 'asc' ? aVal - bVal : bVal - aVal;
      }
    });

    // ソートインジケーター更新
    container.querySelectorAll('.sort-indicator').forEach(indicator => {
      indicator.textContent = '↕';
    });
    const activeHeader = container.querySelector(`[data-sort="${column}"] .sort-indicator`);
    if (activeHeader) {
      activeHeader.textContent = sortDirection === 'asc' ? '↑' : '↓';
    }

    renderRows(currentData);
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  function hideError() {
    container.querySelector('#error-message').classList.add('hidden');
  }

  // CSVエクスポート
  function exportCSV() {
    if (!currentData || currentData.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['順位', '店舗名', '商品名', 'MAPE', 'RMSE', '精度', '期間'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
      currentData.map((row, index) => {
        const store = tables.find(t => t.tableName === '店舗マスタ')?.records?.find(s => s.店舗ID === row.店舗ID);
        const product = tables.find(t => t.tableName === '商品マスタ')?.records?.find(p => p.商品ID === row.商品ID);
        const mape = calculateMAPE(row.予測数量, row.実績数量);
        const rmse = calculateRMSE(row.予測数量, row.実績数量);
        const accuracy = Math.max(0, 100 - mape);

        return [
          index + 1,
          `"${store?.店舗名 || '不明'}"`,
          `"${product?.商品名 || '不明'}"`,
          `${mape.toFixed(2)}%`,
          rmse.toFixed(2),
          `${accuracy.toFixed(1)}%`,
          new Date(row.予測対象日).toLocaleDateString()
        ].join(',');
      }).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `予測精度レポート_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  initStoreOptions();

  // 初期データ読み込み
  window.aivicApi.list(4).then(rows => {
    if (rows) {
      currentData = rows;
      renderRows(rows);
      hideError();
    } else {
      showError('データの取得に失敗しました。ネットワーク接続を確認してください。');
    }
  });

  // グラフ描画
  setTimeout(() => {
    drawAccuracyChart();
    drawComparisonChart();
  }, 100);

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const period = container.querySelector('#period-filter').value;
    const storeId = container.querySelector('#store-filter').value;
    const category = container.querySelector('#category-filter').value;
    const keyword = container.querySelector('#input-search').value;

    try {
      const rows = await window.aivicApi.list(4);
      if (rows) {
        let filtered = rows;

        // 期間フィルター
        const cutoffDate = new Date();
        cutoffDate.setDate(cutoffDate.getDate() - parseInt(period));
        filtered = filtered.filter(row => new Date(row.予測対象日) >= cutoffDate);

        // 店舗フィルター
        if (storeId) {
          filtered = filtered.filter(row => row.店舗ID === storeId);
        }

        // カテゴリフィルター
        if (category) {
          const categoryProducts = tables.find(t => t.tableName === '商品マスタ')?.records?.filter(p => p.商品カテゴリ === category) || [];
          const categoryProductIds = categoryProducts.map(p => p.商品ID);
          filtered = filtered.filter(row => categoryProductIds.includes(row.商品ID));
        }

        // キーワード検索
        if (keyword) {
          filtered = filtered.filter(row => {
            const store = tables.find(t => t.tableName === '店舗マスタ')?.records?.find(s => s.店舗ID === row.店舗ID);
            const product = tables.find(t => t.tableName === '商品マスタ')?.records?.find(p => p.商品ID === row.商品ID);
            return (store?.店舗名 || '').includes(keyword) || (product?.商品名 || '').includes(keyword);
          });
        }

        currentData = filtered;
        renderRows(filtered);
        hideError();
      } else {
        showError('データの取得に失敗しました。');
      }
    } catch (error) {
      showError('検索中にエラーが発生しました。');
    }
  });

  // エクスポート機能
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 再試行機能
  container.querySelector('#btn-retry').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(4);
    if (rows) {
      currentData = rows;
      renderRows(rows);
      hideError();
    }
  });

  // ソート機能
  container.addEventListener('click', (e) => {
    const sortHeader = e.target.closest('.sortable');
    if (sortHeader) {
      const column = sortHeader.dataset.sort;
      sortData(column);
    }

    // 詳細分析ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      window.showScreen('scr-1778591838939');
    }
  });

  // オフライン検知
  window.addEventListener('offline', () => {
    showError('ネットワークに接続できません。接続を確認してください。');
  });

  window.addEventListener('online', () => {
    hideError();
  });
}
